/**
 * Lead Service
 *
 * Manages lead (customer contact) CRUD operations using Sequelize ORM.
 * Leads are auto-created from incoming WhatsApp messages.
 *
 * Phase D: Sequelize implementation with soft deletes (paranoid mode)
 */

import { Lead, WhatsAppLine } from '../models/sequelize/associations.js';
import { Op } from 'sequelize';

class LeadService {
  /**
   * Create a new lead or find existing one by phone number
   * @param {Object} leadData - Lead information
   * @param {string} leadData.phone_number - Customer phone number (E.164 format)
   * @param {number} leadData.company_id - Company ID (required for segmentation)
   * @param {string} [leadData.name] - Customer name
   * @param {string} [leadData.email] - Customer email
   * @param {Date} [leadData.first_contact_date] - First contact timestamp
   * @returns {Promise<Object>} Created or existing lead
   */
  async findOrCreateLead(leadData) {
    try {
      const [lead, created] = await Lead.findOrCreate({
        where: {
          phone_number: leadData.phone_number,
          company_id: leadData.company_id
        },
        defaults: {
          name: leadData.name || null,
          email: leadData.email || null,
          company_id: leadData.company_id,
          status: 'new',
          first_contact_date: leadData.first_contact_date || new Date(),
        },
      });

      return {
        lead: lead.toJSON(),
        created,
      };
    } catch (error) {
      throw new Error(`Error creating/finding lead: ${error.message}`);
    }
  }

  /**
   * Get lead by ID
   * @param {number} leadId - Lead ID
   * @returns {Promise<Object|null>} Lead object or null
   */
  async getLeadById(leadId) {
    try {
      const lead = await Lead.findByPk(leadId);
      return lead ? lead.toJSON() : null;
    } catch (error) {
      throw new Error(`Error fetching lead: ${error.message}`);
    }
  }

  /**
   * Get lead by phone number
   * @param {string} phoneNumber - Phone number (E.164 format)
   * @returns {Promise<Object|null>} Lead object or null
   */
  async getLeadByPhone(phoneNumber) {
    try {
      const lead = await Lead.findOne({
        where: { phone_number: phoneNumber },
      });
      return lead ? lead.toJSON() : null;
    } catch (error) {
      throw new Error(`Error fetching lead by phone: ${error.message}`);
    }
  }

  /**
   * Update lead information
   * @param {number} leadId - Lead ID
   * @param {Object} updates - Fields to update
   * @returns {Promise<Object>} Updated lead
   */
  async updateLead(leadId, updates) {
    try {
      const lead = await Lead.findByPk(leadId);

      if (!lead) {
        throw new Error('Lead not found');
      }

      // Only update allowed fields
      const allowedFields = ['name', 'email', 'status', 'notes'];
      const filteredUpdates = {};

      for (const field of allowedFields) {
        if (updates[field] !== undefined) {
          filteredUpdates[field] = updates[field];
        }
      }

      await lead.update(filteredUpdates);
      return lead.toJSON();
    } catch (error) {
      throw new Error(`Error updating lead: ${error.message}`);
    }
  }

  /**
   * Search leads with filters and pagination
   * @param {Object} options - Search options
   * @param {string} [options.search] - Search term for name or phone
   * @param {string} [options.status] - Filter by status
   * @param {number} [options.companyId] - Filter by company ID
   * @param {number} [options.limit=50] - Results per page
   * @param {number} [options.offset=0] - Pagination offset
   * @returns {Promise<Object>} Leads array and total count
   */
  async searchLeads(options = {}) {
    try {
      const {
        search,
        status,
        companyId,
        limit = 50,
        offset = 0,
      } = options;

      const where = {};

      // Search by name or phone
      if (search) {
        where[Op.or] = [
          { name: { [Op.like]: `%${search}%` } },
          { phone_number: { [Op.like]: `%${search}%` } },
        ];
      }

      // Filter by status
      if (status) {
        where.status = status;
      }

      // Filter by company
      if (companyId !== undefined) {
        where.company_id = companyId;
      }

      const { count, rows } = await Lead.findAndCountAll({
        where,
        limit: parseInt(limit),
        offset: parseInt(offset),
        order: [['created_at', 'DESC']],
      });

      return {
        leads: rows.map(lead => lead.toJSON()),
        total: count,
        limit: parseInt(limit),
        offset: parseInt(offset),
      };
    } catch (error) {
      throw new Error(`Error searching leads: ${error.message}`);
    }
  }

  /**
   * Soft delete a lead
   * @param {number} leadId - Lead ID
   * @returns {Promise<boolean>} Success status
   */
  async deleteLead(leadId) {
    try {
      const lead = await Lead.findByPk(leadId);

      if (!lead) {
        throw new Error('Lead not found');
      }

      await lead.destroy(); // Soft delete (sets deleted_at)
      return true;
    } catch (error) {
      throw new Error(`Error deleting lead: ${error.message}`);
    }
  }

  /**
   * Restore a soft-deleted lead
   * @param {number} leadId - Lead ID
   * @returns {Promise<Object>} Restored lead
   */
  async restoreLead(leadId) {
    try {
      const lead = await Lead.findByPk(leadId, {
        paranoid: false, // Include soft-deleted records
      });

      if (!lead) {
        throw new Error('Lead not found');
      }

      if (!lead.deleted_at) {
        throw new Error('Lead is not deleted');
      }

      await lead.restore();
      return lead.toJSON();
    } catch (error) {
      throw new Error(`Error restoring lead: ${error.message}`);
    }
  }

  /**
   * Get lead statistics by status
   * @returns {Promise<Object>} Status counts
   */
  async getLeadStats() {
    try {
      const stats = await Lead.findAll({
        attributes: [
          'status',
          [sequelize.fn('COUNT', sequelize.col('id')), 'count'],
        ],
        group: ['status'],
      });

      const result = {
        new: 0,
        contacted: 0,
        qualified: 0,
        converted: 0,
        lost: 0,
      };

      stats.forEach(stat => {
        result[stat.status] = parseInt(stat.get('count'));
      });

      return result;
    } catch (error) {
      throw new Error(`Error fetching lead stats: ${error.message}`);
    }
  }
}

export default new LeadService();

