     1→/**
     2→ * Webhook Service
     3→ *
     4→ * Handles incoming WhatsApp Cloud API webhook events.
     5→ * Processes incoming messages, status updates, template status updates, and creates leads automatically.
     6→ *
     7→ * Phase D: Sequelize implementation
     8→ * Phase 10: Added template status update processing
     9→ */
    10→
    11→import crypto from 'crypto';
    12→import { Message, Lead, WhatsAppLine, MessageTemplate, PhoneLine, ConversationAssignment } from '../models/sequelize/associations.js';
    13→import { Op } from 'sequelize';
    14→import MessageService from './MessageService.js';
    15→import LeadService from './LeadService.js';
    16→import SocketService from './SocketService.js';
    17→import MediaDownloadService from './MediaDownloadService.js';
    18→import AutomationService from './AutomationService.js';
    19→import { getPhoneVariations, normalizePhoneNumber } from '../utils/phoneNormalization.js';
    20→import { isWithinBusinessHours } from '../utils/businessHours.js';
    21→import WhatsAppApiClient from './whatsapp/WhatsAppApiClient.js';
    22→
    23→class WebhookService {
    24→  /**
    25→   * Process incoming webhook payload from WhatsApp Cloud API
    26→   * @param {Object} payload - Webhook payload
    27→   * @returns {Promise<Object>} Processing result
    28→   */
    29→  async processWebhook(payload) {
    30→    try {
    31→      if (!payload.entry || !Array.isArray(payload.entry)) {
    32→        return { success: false, error: 'Invalid webhook payload' };
    33→      }
    34→
    35→      const results = [];
    36→
    37→      for (const entry of payload.entry) {
    38→        if (!entry.changes || !Array.isArray(entry.changes)) {
    39→          continue;
    40→        }
    41→
    42→        for (const change of entry.changes) {
    43→          if (change.field === 'messages') {
    44→            const result = await this.processMessagesChange(change.value);
    45→            results.push(result);
    46→          } else if (change.field === 'message_template_status_update') {
    47→            const result = await this.processTemplateStatusUpdate(change.value);
    48→            results.push(result);
    49→          }
    50→        }
    51→      }
    52→
    53→      return {
    54→        success: true,
    55→        results,
    56→      };
    57→    } catch (error) {
    58→      console.error('Webhook processing error:', error);
    59→      return {
    60→        success: false,
    61→        error: error.message,
    62→      };
    63→    }
    64→  }
    65→
    66→  /**
    67→   * Process messages change from webhook
    68→   * @param {Object} value - Messages change value
    69→   * @returns {Promise<Object>} Processing result
    70→   */
    71→  async processMessagesChange(value) {
    72→    try {
    73→
    74→
    75→      const { metadata, contacts, messages, statuses } = value;
    76→
    77→      if (!metadata || !metadata.phone_number_id) {
    78→        throw new Error('Missing metadata in webhook payload');
    79→      }
    80→
    81→      // Find the WhatsApp line by phone_number_id
    82→      const line = await WhatsAppLine.findOne({
    83→        where: { phone_number_id: metadata.phone_number_id },
    84→      });
    85→
    86→      if (!line) {
    87→        throw new Error(`WhatsApp line not found for phone_number_id: ${metadata.phone_number_id}`);
    88→      }
    89→
    90→      const result = {
    91→        line_id: line.id,
    92→        messages_processed: 0,
    93→        statuses_processed: 0,
    94→      };
    95→
    96→      // Process incoming messages
    97→      if (messages && Array.isArray(messages)) {
    98→        for (const message of messages) {
    99→          await this.processIncomingMessage(line.id, message, contacts);
   100→          result.messages_processed++;
   101→        }
   102→      }
   103→
   104→      // Process message status updates
   105→      if (statuses && Array.isArray(statuses)) {
   106→        for (const status of statuses) {
   107→          await this.processMessageStatus(status);
   108→          result.statuses_processed++;
   109→        }
   110→      }
   111→
   112→      return result;
   113→    } catch (error) {
   114→      console.error('Error processing messages change:', error);
   115→      throw error;
   116→    }
   117→  }
   118→
   119→  /**
   120→   * Process an incoming WhatsApp message
   121→   * @param {number} lineId - WhatsApp line ID
   122→   * @param {Object} message - Message object from webhook
   123→   * @param {Array} contacts - Contacts array from webhook
   124→   * @returns {Promise<Object>} Created message
   125→   */
   126→  async processIncomingMessage(lineId, message, contacts) {
   127→    try {
   128→      const { from, id: meta_message_id, timestamp, type } = message;
   129→
   130→      if (!from || !meta_message_id) {
   131→        throw new Error('Invalid message format');
   132→      }
   133→
   134→      // Get line to obtain company_id
   135→      const line = await WhatsAppLine.findByPk(lineId);
   136→      if (!line) {
   137→        throw new Error(`WhatsApp line ${lineId} not found`);
   138→      }
   139→
   140→      // Normalize phone number to ensure consistency (with + prefix)
   141→      const normalizedPhone = normalizePhoneNumber(from);
   142→
   143→      // Find or create lead (with company_id)
   144→      const contactInfo = contacts?.find(c => c.wa_id === from);
   145→      const leadName = contactInfo?.profile?.name || null;
   146→
   147→      const { lead } = await LeadService.findOrCreateLead({
   148→        phone_number: normalizedPhone, // Use normalized phone with + prefix
   149→        company_id: line.company_id,
   150→        name: leadName,
   151→        first_contact_date: new Date(parseInt(timestamp) * 1000),
   152→      });
   153→
   154→      // Extract message content based on type
   155→      let messageContent = '';
   156→      let fileUrl = null;
   157→      let messageType = 'text';
   158→      let interactiveType = null;
   159→      let interactiveData = null;
   160→
   161→
   162→
   163→      switch (type) {
   164→        case 'text':
   165→          messageContent = message.text?.body || '';
   166→          messageType = 'text';
   167→          break;
   168→
   169→        case 'image':
   170→          messageContent = message.image?.caption || '[Image]';
   171→          fileUrl = message.image?.id || null; // Store media ID, actual URL retrieved later
   172→          messageType = 'image';
   173→          break;
   174→
   175→        case 'audio':
   176→          messageContent = '[Audio message]';
   177→          fileUrl = message.audio?.id || null;
   178→          messageType = 'audio';
   179→          break;
   180→
   181→        case 'video':
   182→          messageContent = message.video?.caption || '[Video]';
   183→          fileUrl = message.video?.id || null;
   184→          messageType = 'video';
   185→          break;
   186→
   187→        case 'document':
   188→          messageContent = message.document?.filename || '[Document]';
   189→          fileUrl = message.document?.id || null;
   190→          messageType = 'document';
   191→          break;
   192→
   193→        case 'interactive':
   194→          // Handle interactive message responses (button clicks, list selections)
   195→          if (message.interactive?.type === 'button_reply') {
   196→            // Quick reply button response
   197→            const buttonReply = message.interactive.button_reply;
   198→            messageContent = buttonReply?.title || '[Button Response]';
   199→            messageType = 'interactive';
   200→            interactiveType = 'button_reply';
   201→            interactiveData = {
   202→              id: buttonReply?.id,
   203→              title: buttonReply?.title
   204→            };
   205→
   206→            // Trigger automation for button reply
   207→            await this.processButtonReply(lineId, lead.id, from, buttonReply);
   208→          } else if (message.interactive?.type === 'list_reply') {
   209→            // List selection response
   210→            const listReply = message.interactive.list_reply;
   211→            messageContent = listReply?.title || '[List Selection]';
   212→            messageType = 'interactive';
   213→            interactiveType = 'list_reply';
   214→            interactiveData = {
   215→              id: listReply?.id,
   216→              title: listReply?.title,
   217→              description: listReply?.description
   218→            };
   219→          } else {
   220→            messageContent = '[Interactive message]';
   221→            messageType = 'interactive';
   222→          }
   223→          break;
   224→
   225→        case 'button':
   226→          // Handle quick reply button (from template)
   227→          messageContent = message.button?.text || '[Button Click]';
   228→          messageType = 'button_reply';
   229→
   230→          // Trigger automation for button reply
   231→          await this.processButtonReply(lineId, lead.id, from, {
   232→            id: message.button?.payload,
   233→            title: message.button?.text
   234→          });
   235→          break;
   236→
   237→        default:
   238→          messageContent = `[Unsupported message type: ${type}]`;
   239→          messageType = 'text';
   240→      }
   241→
   242→      // Download media if message contains media ID
   243→      let finalFileUrl = fileUrl;
   244→      const mediaTypes = ['audio', 'video', 'image', 'document'];
   245→
   246→      if (fileUrl && mediaTypes.includes(messageType)) {
   247→        try {
   248→
   249→          // Get WhatsApp line for credentials
   250→          const whatsAppLine = await WhatsAppLine.findByPk(lineId);
   251→
   252→          if (whatsAppLine) {
   253→            const downloadResult = await MediaDownloadService.downloadAndSaveMedia(
   254→              fileUrl,
   255→              whatsAppLine,
   256→              messageType
   257→            );
   258→
   259→            finalFileUrl = downloadResult.publicUrl;
   260→          }
   261→        } catch (downloadError) {
   262→          console.error('Failed to download media, using media ID as fallback:', downloadError);
   263→          // Keep the media ID as fallback
   264→        }
   265→      }
   266→
   267→      // Normalize phone number - try both with and without + prefix
   268→      const phoneVariations = getPhoneVariations(from);
   269→
   270→      // STEP 1: Check if a persistent conversation assignment exists
   271→      // CRITICAL: Find the LATEST assignment (by assigned_at) to ensure replies
   272→      // go to the LAST user who contacted this number
   273→      let conversationAssignment = await ConversationAssignment.findOne({
   274→        where: {
   275→          phone_number: { [Op.in]: phoneVariations },
   276→          line_id: lineId,
   277→        },
   278→        order: [['assigned_at', 'DESC']]  // Get the most recent assignment
   279→      });
   280→
   281→      // Determine context: campaign or general
   282→      let contextCampaignId = null;
   283→      let contextAssignedUserIds = null;
   284→
   285→      if (conversationAssignment) {
   286→        // STEP 2A: Use existing assignment (persisted context)
   287→        console.log('[WebhookService] ✓ Found latest conversation assignment:', {
   288→          phone_number: conversationAssignment.phone_number,
   289→          campaign_id: conversationAssignment.campaign_id,
   290→          assigned_user_id: conversationAssignment.assigned_user_id,
   291→          assigned_at: conversationAssignment.assigned_at
   292→        });
   293→
   294→        contextCampaignId = conversationAssignment.campaign_id;
   295→        contextAssignedUserIds = conversationAssignment.assigned_user_id ? [conversationAssignment.assigned_user_id] : null;
   296→      } else {
   297→        // STEP 2B: No assignment exists - search for original campaign (NO TIME LIMIT)
   298→        // This fixes the 48-hour bug: conversations stay with their campaign forever
   299→        const campaignMessage = await Message.findOne({
   300→          where: {
   301→            phone_number: { [Op.in]: phoneVariations },
   302→            line_id: lineId,
   303→            is_mass_campaign: true,
   304→            direction: 'outgoing',
   305→            campaign_id: { [Op.ne]: null },
   306→          },
   307→          order: [['created_at', 'DESC']],
   308→          attributes: ['id', 'campaign_id', 'assigned_user_id', 'assigned_user_ids', 'created_at', 'phone_number', 'line_id']
   309→        });
   310→
   311→        if (campaignMessage) {
   312→          contextCampaignId = campaignMessage.campaign_id;
   313→          contextAssignedUserIds = campaignMessage.assigned_user_ids || (campaignMessage.assigned_user_id ? [campaignMessage.assigned_user_id] : null);
   314→
   315→          // STEP 3: Create persistent assignment for future messages
   316→          conversationAssignment = await ConversationAssignment.create({
   317→            phone_number: normalizedPhone,
   318→            line_id: lineId,
   319→            assigned_user_id: contextAssignedUserIds && contextAssignedUserIds.length > 0 ? contextAssignedUserIds[0] : null,
   320→            assigned_at: new Date(),
   321→            assigned_by_user_id: null, // System-assigned from campaign
   322→            campaign_id: contextCampaignId
   323→          });
   324→
   325→          console.log('[WebhookService] ✓ Created conversation assignment from campaign:', {
   326→            phone_number: normalizedPhone,
   327→            campaign_id: contextCampaignId,
   328→            assigned_user_id: conversationAssignment.assigned_user_id
   329→          });
   330→        } else {
   331→          console.log('[WebhookService] ✗ No campaign found - Using general conversation context');
   332→        }
   333→      }
   334→
   335→      // Normalize phone number to ensure consistency (with + prefix)
   336→     // const normalizedPhone = normalizePhoneNumber(from);
   337→
   338→      // Save incoming message with context
   339→      const savedMessage = await MessageService.saveIncomingMessage({
   340→        line_id: lineId,
   341→        lead_id: lead.id,
   342→        company_id: line.company_id,
   343→        phone_number: normalizedPhone, // Use normalized phone with + prefix
   344→        message_content: messageContent,
   345→        message_type: messageType,
   346→        file_url: finalFileUrl,
   347→        meta_message_id,
   348→        reply_to_message_id: null, // Note: message.context?.id is a meta_message_id (string), not our internal message ID
   349→        campaign_id: contextCampaignId,
   350→        assigned_user_id: contextAssignedUserIds && contextAssignedUserIds.length > 0 ? contextAssignedUserIds[0] : null, // Keep first for backward compatibility
   351→        assigned_user_ids: contextAssignedUserIds, // Array of assigned agents
   352→        interactive_type: interactiveType,
   353→        interactive_data: interactiveData,
   354→      });
   355→
   356→      console.log('[WebhookService] Saved message:', {
   357→        messageId: savedMessage.id,
   358→        campaignId: savedMessage.campaign_id,
   359→        assignedUserId: savedMessage.assigned_user_id,
   360→        context: savedMessage.campaign_id ? 'campaign' : 'general'
   361→      });
   362→
   363→      // Skip automation for campaign responses
   364→      const isCampaignResponse = savedMessage.campaign_id && savedMessage.assigned_user_id;
   365→      if (isCampaignResponse) {
   366→        console.log('[WebhookService] Skipping automation for campaign response');
   367→      } else {
   368→        // Check if this is the first message from this contact (trigger welcome automation)
   369→        const previousMessageCount = await Message.count({
   370→          where: {
   371→            phone_number: normalizedPhone,
   372→            line_id: lineId,
   373→            direction: 'incoming'
   374→          }
   375→        });
   376→
   377→        // Only trigger automation on first message to avoid spam
   378→        if (previousMessageCount === 1) {
   379→          console.log('[WebhookService] First message from contact - triggering automation');
   380→          await this.processMessageAutomation(lineId, lead.id, normalizedPhone, messageContent, messageType);
   381→        } else {
   382→          console.log(`[WebhookService] Skipping automation - not first message (count: ${previousMessageCount})`);
   383→        }
   384→      }
   385→
   386→      // Emit Socket.IO event for real-time notification
   387→      await SocketService.emitIncomingMessage(lineId, savedMessage);
   388→
   389→      return savedMessage;
   390→    } catch (error) {
   391→      console.error('Error processing incoming message:', error);
   392→      throw error;
   393→    }
   394→  }
   395→
   396→  /**
   397→   * Process message status update
   398→   * @param {Object} status - Status object from webhook
   399→   * @returns {Promise<Object|null>} Updated message or null
   400→   */
   401→  async processMessageStatus(status) {
   402→    try {
   403→      const { id: meta_message_id, status: newStatus } = status;
   404→
   405→      if (!meta_message_id || !newStatus) {
   406→        return null;
   407→      }
   408→
   409→      // Map Meta status to our status values
   410→      const statusMap = {
   411→        sent: 'sent',
   412→        delivered: 'delivered',
   413→        read: 'read',
   414→        failed: 'failed',
   415→      };
   416→
   417→      const mappedStatus = statusMap[newStatus];
   418→      if (!mappedStatus) {
   419→        return null;
   420→      }
   421→
   422→      const updatedMessage = await MessageService.updateMessageStatus(
   423→        meta_message_id,
   424→        mappedStatus
   425→      );
   426→
   427→      if (updatedMessage) {
   428→        // Emit Socket.IO event for status update
   429→        SocketService.emitMessageStatusUpdate(updatedMessage);
   430→      }
   431→
   432→      return updatedMessage;
   433→    } catch (error) {
   434→      console.error('Error processing message status:', error);
   435→      throw error;
   436→    }
   437→  }
   438→
   439→  /**
   440→   * Process template status update from webhook
   441→   * Handles APPROVED, REJECTED, and PENDING status updates from Meta
   442→   * @param {Object} value - Template status update value from webhook
   443→   * @returns {Promise<Object>} Processing result
   444→   */
   445→  async processTemplateStatusUpdate(value) {
   446→    try {
   447→      console.log('Processing template status update:', JSON.stringify(value, null, 2));
   448→
   449→      // Extract template information from webhook payload
   450→      const { message_template_id, message_template_name, event } = value;
   451→
   452→      if (!message_template_id || !event) {
   453→        console.warn('Missing required fields in template status update');
   454→        return {
   455→          success: false,
   456→          error: 'Missing required fields: message_template_id or event'
   457→        };
   458→      }
   459→
   460→      // Map Meta event to our status values
   461→      const statusMap = {
   462→        'APPROVED': 'approved',
   463→        'REJECTED': 'rejected',
   464→        'PENDING': 'pending',
   465→        'DISABLED': 'rejected', // Treat disabled as rejected
   466→        'PAUSED': 'pending', // Treat paused as pending
   467→      };
   468→
   469→      const newStatus = statusMap[event];
   470→      if (!newStatus) {
   471→        console.warn(`Unknown template status event: ${event}`);
   472→        return {
   473→          success: false,
   474→          error: `Unknown event: ${event}`
   475→        };
   476→      }
   477→
   478→      // Find template by meta_template_id
   479→      const template = await MessageTemplate.findOne({
   480→        where: { meta_template_id: message_template_id.toString() },
   481→        include: [{
   482→          model: WhatsAppLine,
   483→          as: 'line'
   484→        }]
   485→      });
   486→
   487→      if (!template) {
   488→        // Template might not exist yet if this is a very quick response
   489→        // or if template was created directly in Meta's dashboard
   490→        console.warn(`Template not found for meta_template_id: ${message_template_id}`);
   491→        return {
   492→          success: false,
   493→          error: `Template not found: ${message_template_id}`
   494→        };
   495→      }
   496→
   497→      // Update template status
   498→      const previousStatus = template.status;
   499→      await template.update({
   500→        status: newStatus,
   501→        rejection_reason: event === 'REJECTED' ?
   502→          (value.rejection_reason || 'Template rejected by Meta') :
   503→          null
   504→      });
   505→
   506→      console.log(`Template ${template.id} status updated: ${previousStatus} → ${newStatus}`);
   507→
   508→      // Emit Socket.IO event for real-time notification
   509→      if (SocketService.emitTemplateStatusUpdate) {
   510→        SocketService.emitTemplateStatusUpdate(template.line_id, {
   511→          template_id: template.id,
   512→          template_name: template.name,
   513→          status: newStatus,
   514→          previous_status: previousStatus,
   515→          rejection_reason: template.rejection_reason,
   516→          meta_template_id: message_template_id
   517→        });
   518→      }
   519→
   520→      return {
   521→        success: true,
   522→        template_id: template.id,
   523→        template_name: template.name,
   524→        previous_status: previousStatus,
   525→        new_status: newStatus
   526→      };
   527→    } catch (error) {
   528→      console.error('Error processing template status update:', error);
   529→      return {
   530→        success: false,
   531→        error: error.message
   532→      };
   533→    }
   534→  }
   535→
   536→  /**
   537→   * Process incoming message automation (auto-responses)
   538→   * Checks business hours and sends out-of-hours message if configured
   539→   * @param {number} lineId - WhatsApp line ID
   540→   * @param {number} leadId - Lead ID
   541→   * @param {string} phoneNumber - Sender's phone number
   542→   * @param {string} messageContent - Message content
   543→   * @param {string} messageType - Message type
   544→   * @returns {Promise<Array>} Executed automations
   545→   */
   546→  async processMessageAutomation(lineId, leadId, phoneNumber, messageContent, messageType) {
   547→    try {
   548→      console.log('[WebhookService] Processing message automation:', { lineId, messageContent, messageType });
   549→
   550→      // Only process text messages for keyword matching
   551→      if (messageType !== 'text' || !messageContent) {
   552→        return [];
   553→      }
   554→
   555→      // Load phone line configuration to check business hours
   556→      const phoneLine = await PhoneLine.findOne({
   557→        where: { id: lineId }
   558→      });
   559→
   560→      if (!phoneLine) {
   561→        console.error('[WebhookService] Phone line not found:', lineId);
   562→        return [];
   563→      }
   564→
   565→      // Check if current time is within business hours
   566→      const withinBusinessHours = isWithinBusinessHours(phoneLine.business_hours);
   567→
   568→      console.log('[WebhookService] Business hours check:', {
   569→        lineId,
   570→        businessHoursEnabled: phoneLine.business_hours?.enabled || false,
   571→        withinBusinessHours,
   572→        timezone: phoneLine.business_hours?.timezone || 'UTC'
   573→      });
   574→
   575→      // If outside business hours and out_of_hours_message is configured, send it
   576→      if (!withinBusinessHours && phoneLine.out_of_hours_message) {
   577→        console.log('[WebhookService] Outside business hours - sending out_of_hours_message');
   578→
   579→        try {
   580→          // Get WhatsApp line for API credentials
   581→          const whatsAppLine = await WhatsAppLine.findByPk(lineId);
   582→
   583→          if (whatsAppLine) {
   584→            const apiClient = new WhatsAppApiClient({
   585→              phoneNumberId: whatsAppLine.phone_number_id,
   586→              accessToken: whatsAppLine.access_token,
   587→              businessAccountId: whatsAppLine.business_account_id
   588→            });
   589→
   590→            await apiClient.sendTextMessage(phoneNumber, phoneLine.out_of_hours_message);
   591→
   592→            console.log('[WebhookService] Out of hours message sent successfully');
   593→          }
   594→        } catch (sendError) {
   595→          console.error('[WebhookService] Error sending out of hours message:', sendError);
   596→        }
   597→
   598→        // Don't process regular automations when outside business hours
   599→        return [{
   600→          type: 'out_of_hours_message',
   601→          message: phoneLine.out_of_hours_message
   602→        }];
   603→      }
   604→
   605→      // Within business hours or no out_of_hours_message configured - process normal automations
   606→      const automationResults = [];
   607→
   608→      // 1. Check for keyword triggers (exact and partial matches)
   609→      const keywordResults = await AutomationService.processTrigger({
   610→        lineId,
   611→        triggerType: 'KEYWORD',
   612→        triggerValue: messageContent.trim(),
   613→        templateId: null,
   614→        context: {
   615→          leadId,
   616→          phoneNumber,
   617→          messageContent,
   618→          messageType
   619→        }
   620→      });
   621→      automationResults.push(...keywordResults);
   622→
   623→      // 2. Check for general MESSAGE_RECEIVED triggers (catch-all auto-responses)
   624→      // These are rules without specific trigger_value that apply to any message
   625→      const generalResults = await AutomationService.processTrigger({
   626→        lineId,
   627→        triggerType: 'MESSAGE_RECEIVED',
   628→        triggerValue: null,
   629→        templateId: null,
   630→        context: {
   631→          leadId,
   632→          phoneNumber,
   633→          messageContent,
   634→          messageType
   635→        }
   636→      });
   637→      automationResults.push(...generalResults);
   638→
   639→      if (automationResults.length > 0) {
   640→        console.log('[WebhookService] Automation rules executed:', automationResults.length);
   641→      }
   642→
   643→      return automationResults;
   644→    } catch (error) {
   645→      console.error('[WebhookService] Error processing message automation:', error);
   646→      // Don't throw, automation errors shouldn't break message processing
   647→      return [];
   648→    }
   649→  }
   650→
   651→  /**
   652→   * Process button reply and trigger automations
   653→   * @param {number} lineId - WhatsApp line ID
   654→   * @param {number} leadId - Lead ID
   655→   * @param {string} phoneNumber - Sender's phone number
   656→   * @param {Object} buttonReply - Button reply data
   657→   * @returns {Promise<Array>} Executed automations
   658→   */
   659→  async processButtonReply(lineId, leadId, phoneNumber, buttonReply) {
   660→    try {
   661→      console.log('Processing button reply:', JSON.stringify(buttonReply, null, 2));
   662→
   663→      const { id: buttonId, title: buttonText } = buttonReply;
   664→
   665→      // Trigger automation rules for QUICK_REPLY
   666→      const automationResults = await AutomationService.processTrigger({
   667→        lineId,
   668→        triggerType: 'QUICK_REPLY',
   669→        triggerValue: buttonText,
   670→        templateId: null, // Could be enhanced to track which template triggered this
   671→        context: {
   672→          leadId,
   673→          phoneNumber,
   674→          buttonId,
   675→          buttonText
   676→        }
   677→      });
   678→
   679→      console.log('Automation results:', automationResults);
   680→
   681→      // Emit socket event for button click
   682→      SocketService.emitToLine(lineId, 'button:clicked', {
   683→        leadId,
   684→        phoneNumber,
   685→        buttonId,
   686→        buttonText,
   687→        automationResults
   688→      });
   689→
   690→      return automationResults;
   691→    } catch (error) {
   692→      console.error('Error processing button reply:', error);
   693→      // Don't throw, automation errors shouldn't break message processing
   694→      return [];
   695→    }
   696→  }
   697→
   698→  /**
   699→   * Verify webhook signature (Meta HMAC SHA256)
   700→   * @param {string} signature - X-Hub-Signature-256 header value
   701→   * @param {string} rawBody - Raw request body
   702→   * @param {string} secret - Webhook secret from line configuration
   703→   * @returns {boolean} Verification result
   704→   */
   705→  verifyWebhookSignature(signature, rawBody, secret) {
   706→    try {
   707→      if (!signature || !rawBody || !secret) {
   708→        return false;
   709→      }
   710→
   711→      // Extract the signature value (format: sha256=<signature>)
   712→      const signatureHash = signature.replace('sha256=', '');
   713→
   714→      // Compute HMAC SHA256
   715→      const expectedHash = crypto
   716→        .createHmac('sha256', secret)
   717→        .update(rawBody, 'utf8')
   718→        .digest('hex');
   719→
   720→      // Constant-time comparison
   721→      return crypto.timingSafeEqual(
   722→        Buffer.from(signatureHash, 'hex'),
   723→        Buffer.from(expectedHash, 'hex')
   724→      );
   725→    } catch (error) {
   726→      console.error('Error verifying webhook signature:', error);
   727→      return false;
   728→    }
   729→  }
   730→}
   731→
   732→export default new WebhookService();
