/**
 * Webhook Service
 *
 * Handles incoming WhatsApp Cloud API webhook events.
 * Processes incoming messages, status updates, template status updates, and creates leads automatically.
 *
 * Phase D: Sequelize implementation
 * Phase 10: Added template status update processing
 */

import crypto from 'crypto';
import { Message, Lead, WhatsAppLine, MessageTemplate, PhoneLine, ConversationAssignment } from '../models/sequelize/associations.js';
import { Op } from 'sequelize';
import MessageService from './MessageService.js';
import LeadService from './LeadService.js';
import SocketService from './SocketService.js';
import MediaDownloadService from './MediaDownloadService.js';
import AutomationService from './AutomationService.js';
import { getPhoneVariations, normalizePhoneNumber } from '../utils/phoneNormalization.js';
import { isWithinBusinessHours } from '../utils/businessHours.js';
import WhatsAppApiClient from './whatsapp/WhatsAppApiClient.js';

class WebhookService {
  /**
   * Process incoming webhook payload from WhatsApp Cloud API
   * @param {Object} payload - Webhook payload
   * @returns {Promise<Object>} Processing result
   */
  async processWebhook(payload) {
    try {
      if (!payload.entry || !Array.isArray(payload.entry)) {
        return { success: false, error: 'Invalid webhook payload' };
      }

      const results = [];

      for (const entry of payload.entry) {
        if (!entry.changes || !Array.isArray(entry.changes)) {
          continue;
        }

        for (const change of entry.changes) {
          if (change.field === 'messages') {
            const result = await this.processMessagesChange(change.value);
            results.push(result);
          } else if (change.field === 'message_template_status_update') {
            const result = await this.processTemplateStatusUpdate(change.value);
            results.push(result);
          }
        }
      }

      return {
        success: true,
        results,
      };
    } catch (error) {
      console.error('Webhook processing error:', error);
      return {
        success: false,
        error: error.message,
      };
    }
  }

  /**
   * Process messages change from webhook
   * @param {Object} value - Messages change value
   * @returns {Promise<Object>} Processing result
   */
  async processMessagesChange(value) {
    try {


      const { metadata, contacts, messages, statuses } = value;

      if (!metadata || !metadata.phone_number_id) {
        throw new Error('Missing metadata in webhook payload');
      }

      // Find the WhatsApp line by phone_number_id
      const line = await WhatsAppLine.findOne({
        where: { phone_number_id: metadata.phone_number_id },
      });

      if (!line) {
        throw new Error(`WhatsApp line not found for phone_number_id: ${metadata.phone_number_id}`);
      }

      const result = {
        line_id: line.id,
        messages_processed: 0,
        statuses_processed: 0,
      };

      // Process incoming messages
      if (messages && Array.isArray(messages)) {
        for (const message of messages) {
          await this.processIncomingMessage(line.id, message, contacts);
          result.messages_processed++;
        }
      }

      // Process message status updates
      if (statuses && Array.isArray(statuses)) {
        for (const status of statuses) {
          await this.processMessageStatus(status);
          result.statuses_processed++;
        }
      }

      return result;
    } catch (error) {
      console.error('Error processing messages change:', error);
      throw error;
    }
  }

  /**
   * Process an incoming WhatsApp message
   * @param {number} lineId - WhatsApp line ID
   * @param {Object} message - Message object from webhook
   * @param {Array} contacts - Contacts array from webhook
   * @returns {Promise<Object>} Created message
   */
  async processIncomingMessage(lineId, message, contacts) {
    try {
      const { from, id: meta_message_id, timestamp, type } = message;

      if (!from || !meta_message_id) {
        throw new Error('Invalid message format');
      }

      // Get line to obtain company_id
      const line = await WhatsAppLine.findByPk(lineId);
      if (!line) {
        throw new Error(`WhatsApp line ${lineId} not found`);
      }

      // Normalize phone number to ensure consistency (with + prefix)
      const normalizedPhone = normalizePhoneNumber(from);

      // Find or create lead (with company_id)
      const contactInfo = contacts?.find(c => c.wa_id === from);
      const leadName = contactInfo?.profile?.name || null;

      const { lead } = await LeadService.findOrCreateLead({
        phone_number: normalizedPhone, // Use normalized phone with + prefix
        company_id: line.company_id,
        name: leadName,
        first_contact_date: new Date(parseInt(timestamp) * 1000),
      });

      // Extract message content based on type
      let messageContent = '';
      let fileUrl = null;
      let messageType = 'text';
      let interactiveType = null;
      let interactiveData = null;



      switch (type) {
        case 'text':
          messageContent = message.text?.body || '';
          messageType = 'text';
          break;

        case 'image':
          messageContent = message.image?.caption || '[Image]';
          fileUrl = message.image?.id || null; // Store media ID, actual URL retrieved later
          messageType = 'image';
          break;

        case 'audio':
          messageContent = '[Audio message]';
          fileUrl = message.audio?.id || null;
          messageType = 'audio';
          break;

        case 'video':
          messageContent = message.video?.caption || '[Video]';
          fileUrl = message.video?.id || null;
          messageType = 'video';
          break;

        case 'document':
          messageContent = message.document?.filename || '[Document]';
          fileUrl = message.document?.id || null;
          messageType = 'document';
          break;

        case 'interactive':
          // Handle interactive message responses (button clicks, list selections)
          if (message.interactive?.type === 'button_reply') {
            // Quick reply button response
            const buttonReply = message.interactive.button_reply;
            messageContent = buttonReply?.title || '[Button Response]';
            messageType = 'interactive';
            interactiveType = 'button_reply';
            interactiveData = {
              id: buttonReply?.id,
              title: buttonReply?.title
            };

            // Trigger automation for button reply
            await this.processButtonReply(lineId, lead.id, from, buttonReply);
          } else if (message.interactive?.type === 'list_reply') {
            // List selection response
            const listReply = message.interactive.list_reply;
            messageContent = listReply?.title || '[List Selection]';
            messageType = 'interactive';
            interactiveType = 'list_reply';
            interactiveData = {
              id: listReply?.id,
              title: listReply?.title,
              description: listReply?.description
            };
          } else {
            messageContent = '[Interactive message]';
            messageType = 'interactive';
          }
          break;

        case 'button':
          // Handle quick reply button (from template)
          messageContent = message.button?.text || '[Button Click]';
          messageType = 'button_reply';

          // Trigger automation for button reply
          await this.processButtonReply(lineId, lead.id, from, {
            id: message.button?.payload,
            title: message.button?.text
          });
          break;

        default:
          messageContent = `[Unsupported message type: ${type}]`;
          messageType = 'text';
      }

      // Download media if message contains media ID
      let finalFileUrl = fileUrl;
      const mediaTypes = ['audio', 'video', 'image', 'document'];

      if (fileUrl && mediaTypes.includes(messageType)) {
        try {

          // Get WhatsApp line for credentials
          const whatsAppLine = await WhatsAppLine.findByPk(lineId);

          if (whatsAppLine) {
            const downloadResult = await MediaDownloadService.downloadAndSaveMedia(
              fileUrl,
              whatsAppLine,
              messageType
            );

            finalFileUrl = downloadResult.publicUrl;
          }
        } catch (downloadError) {
          console.error('Failed to download media, using media ID as fallback:', downloadError);
          // Keep the media ID as fallback
        }
      }

      // Normalize phone number - try both with and without + prefix
      const phoneVariations = getPhoneVariations(from);

      // STEP 1: Check if a persistent conversation assignment exists
      // CRITICAL: Find the LATEST assignment (by assigned_at) to ensure replies
      // go to the LAST user who contacted this number
      let conversationAssignment = await ConversationAssignment.findOne({
        where: {
          phone_number: { [Op.in]: phoneVariations },
          line_id: lineId,
        },
        order: [['assigned_at', 'DESC']]  // Get the most recent assignment
      });

      // Determine context: campaign or general
      let contextCampaignId = null;
      let contextAssignedUserIds = null;

      if (conversationAssignment) {
        // STEP 2A: Use existing assignment (persisted context)
        console.log('[WebhookService] ✓ Found latest conversation assignment:', {
          phone_number: conversationAssignment.phone_number,
          campaign_id: conversationAssignment.campaign_id,
          assigned_user_id: conversationAssignment.assigned_user_id,
          assigned_at: conversationAssignment.assigned_at
        });

        contextCampaignId = conversationAssignment.campaign_id;
        contextAssignedUserIds = conversationAssignment.assigned_user_id ? [conversationAssignment.assigned_user_id] : null;
      } else {
        // STEP 2B: No assignment exists - search for original campaign (NO TIME LIMIT)
        // This fixes the 48-hour bug: conversations stay with their campaign forever
        const campaignMessage = await Message.findOne({
          where: {
            phone_number: { [Op.in]: phoneVariations },
            line_id: lineId,
            is_mass_campaign: true,
            direction: 'outgoing',
            campaign_id: { [Op.ne]: null },
          },
          order: [['created_at', 'DESC']],
          attributes: ['id', 'campaign_id', 'assigned_user_id', 'assigned_user_ids', 'created_at', 'phone_number', 'line_id']
        });

        if (campaignMessage) {
          contextCampaignId = campaignMessage.campaign_id;
          contextAssignedUserIds = campaignMessage.assigned_user_ids || (campaignMessage.assigned_user_id ? [campaignMessage.assigned_user_id] : null);

          // STEP 3: Create persistent assignment for future messages
          conversationAssignment = await ConversationAssignment.create({
            phone_number: normalizedPhone,
            line_id: lineId,
            assigned_user_id: contextAssignedUserIds && contextAssignedUserIds.length > 0 ? contextAssignedUserIds[0] : null,
            assigned_at: new Date(),
            assigned_by_user_id: null, // System-assigned from campaign
            campaign_id: contextCampaignId
          });

          console.log('[WebhookService] ✓ Created conversation assignment from campaign:', {
            phone_number: normalizedPhone,
            campaign_id: contextCampaignId,
            assigned_user_id: conversationAssignment.assigned_user_id
          });
        } else {
          console.log('[WebhookService] ✗ No campaign found - Using general conversation context');
        }
      }

      // Normalize phone number to ensure consistency (with + prefix)
     // const normalizedPhone = normalizePhoneNumber(from);

      // Save incoming message with context
      const savedMessage = await MessageService.saveIncomingMessage({
        line_id: lineId,
        lead_id: lead.id,
        company_id: line.company_id,
        phone_number: normalizedPhone, // Use normalized phone with + prefix
        message_content: messageContent,
        message_type: messageType,
        file_url: finalFileUrl,
        meta_message_id,
        reply_to_message_id: null, // Note: message.context?.id is a meta_message_id (string), not our internal message ID
        campaign_id: contextCampaignId,
        assigned_user_id: contextAssignedUserIds && contextAssignedUserIds.length > 0 ? contextAssignedUserIds[0] : null, // Keep first for backward compatibility
        assigned_user_ids: contextAssignedUserIds, // Array of assigned agents
        interactive_type: interactiveType,
        interactive_data: interactiveData,
      });

      console.log('[WebhookService] Saved message:', {
        messageId: savedMessage.id,
        campaignId: savedMessage.campaign_id,
        assignedUserId: savedMessage.assigned_user_id,
        context: savedMessage.campaign_id ? 'campaign' : 'general'
      });

      // Skip automation for campaign responses
      const isCampaignResponse = savedMessage.campaign_id && savedMessage.assigned_user_id;
      if (isCampaignResponse) {
        console.log('[WebhookService] Skipping automation for campaign response');
      } else {
        // Check if this is the first message from this contact (trigger welcome automation)
        const previousMessageCount = await Message.count({
          where: {
            phone_number: normalizedPhone,
            line_id: lineId,
            direction: 'incoming'
          }
        });

        // Only trigger automation on first message to avoid spam
        if (previousMessageCount === 1) {
          console.log('[WebhookService] First message from contact - triggering automation');
          await this.processMessageAutomation(lineId, lead.id, normalizedPhone, messageContent, messageType);
        } else {
          console.log(`[WebhookService] Skipping automation - not first message (count: ${previousMessageCount})`);
        }
      }

      // Emit Socket.IO event for real-time notification
      await SocketService.emitIncomingMessage(lineId, savedMessage);

      return savedMessage;
    } catch (error) {
      console.error('Error processing incoming message:', error);
      throw error;
    }
  }

  /**
   * Process message status update
   * @param {Object} status - Status object from webhook
   * @returns {Promise<Object|null>} Updated message or null
   */
  async processMessageStatus(status) {
    try {
      const { id: meta_message_id, status: newStatus } = status;

      if (!meta_message_id || !newStatus) {
        return null;
      }

      // Map Meta status to our status values
      const statusMap = {
        sent: 'sent',
        delivered: 'delivered',
        read: 'read',
        failed: 'failed',
      };

      const mappedStatus = statusMap[newStatus];
      if (!mappedStatus) {
        return null;
      }

      const updatedMessage = await MessageService.updateMessageStatus(
        meta_message_id,
        mappedStatus
      );

      if (updatedMessage) {
        // Emit Socket.IO event for status update
        SocketService.emitMessageStatusUpdate(updatedMessage);
      }

      return updatedMessage;
    } catch (error) {
      console.error('Error processing message status:', error);
      throw error;
    }
  }

  /**
   * Process template status update from webhook
   * Handles APPROVED, REJECTED, and PENDING status updates from Meta
   * @param {Object} value - Template status update value from webhook
   * @returns {Promise<Object>} Processing result
   */
  async processTemplateStatusUpdate(value) {
    try {
      console.log('Processing template status update:', JSON.stringify(value, null, 2));

      // Extract template information from webhook payload
      const { message_template_id, message_template_name, event } = value;

      if (!message_template_id || !event) {
        console.warn('Missing required fields in template status update');
        return {
          success: false,
          error: 'Missing required fields: message_template_id or event'
        };
      }

      // Map Meta event to our status values
      const statusMap = {
        'APPROVED': 'approved',
        'REJECTED': 'rejected',
        'PENDING': 'pending',
        'DISABLED': 'rejected', // Treat disabled as rejected
        'PAUSED': 'pending', // Treat paused as pending
      };

      const newStatus = statusMap[event];
      if (!newStatus) {
        console.warn(`Unknown template status event: ${event}`);
        return {
          success: false,
          error: `Unknown event: ${event}`
        };
      }

      // Find template by meta_template_id
      const template = await MessageTemplate.findOne({
        where: { meta_template_id: message_template_id.toString() },
        include: [{
          model: WhatsAppLine,
          as: 'line'
        }]
      });

      if (!template) {
        // Template might not exist yet if this is a very quick response
        // or if template was created directly in Meta's dashboard
        console.warn(`Template not found for meta_template_id: ${message_template_id}`);
        return {
          success: false,
          error: `Template not found: ${message_template_id}`
        };
      }

      // Update template status
      const previousStatus = template.status;
      await template.update({
        status: newStatus,
        rejection_reason: event === 'REJECTED' ?
          (value.rejection_reason || 'Template rejected by Meta') :
          null
      });

      console.log(`Template ${template.id} status updated: ${previousStatus} → ${newStatus}`);

      // Emit Socket.IO event for real-time notification
      if (SocketService.emitTemplateStatusUpdate) {
        SocketService.emitTemplateStatusUpdate(template.line_id, {
          template_id: template.id,
          template_name: template.name,
          status: newStatus,
          previous_status: previousStatus,
          rejection_reason: template.rejection_reason,
          meta_template_id: message_template_id
        });
      }

      return {
        success: true,
        template_id: template.id,
        template_name: template.name,
        previous_status: previousStatus,
        new_status: newStatus
      };
    } catch (error) {
      console.error('Error processing template status update:', error);
      return {
        success: false,
        error: error.message
      };
    }
  }

  /**
   * Process incoming message automation (auto-responses)
   * Checks business hours and sends out-of-hours message if configured
   * @param {number} lineId - WhatsApp line ID
   * @param {number} leadId - Lead ID
   * @param {string} phoneNumber - Sender's phone number
   * @param {string} messageContent - Message content
   * @param {string} messageType - Message type
   * @returns {Promise<Array>} Executed automations
   */
  async processMessageAutomation(lineId, leadId, phoneNumber, messageContent, messageType) {
    try {
      console.log('[WebhookService] Processing message automation:', { lineId, messageContent, messageType });

      // Only process text messages for keyword matching
      if (messageType !== 'text' || !messageContent) {
        return [];
      }

      // Load phone line configuration to check business hours
      const phoneLine = await PhoneLine.findOne({
        where: { id: lineId }
      });

      if (!phoneLine) {
        console.error('[WebhookService] Phone line not found:', lineId);
        return [];
      }

      // Check if current time is within business hours
      const withinBusinessHours = isWithinBusinessHours(phoneLine.business_hours);

      console.log('[WebhookService] Business hours check:', {
        lineId,
        businessHoursEnabled: phoneLine.business_hours?.enabled || false,
        withinBusinessHours,
        timezone: phoneLine.business_hours?.timezone || 'UTC'
      });

      // If outside business hours and out_of_hours_message is configured, send it
      if (!withinBusinessHours && phoneLine.out_of_hours_message) {
        console.log('[WebhookService] Outside business hours - sending out_of_hours_message');

        try {
          // Get WhatsApp line for API credentials
          const whatsAppLine = await WhatsAppLine.findByPk(lineId);

          if (whatsAppLine) {
            const apiClient = new WhatsAppApiClient({
              phoneNumberId: whatsAppLine.phone_number_id,
              accessToken: whatsAppLine.access_token,
              businessAccountId: whatsAppLine.business_account_id
            });

            await apiClient.sendTextMessage(phoneNumber, phoneLine.out_of_hours_message);

            console.log('[WebhookService] Out of hours message sent successfully');
          }
        } catch (sendError) {
          console.error('[WebhookService] Error sending out of hours message:', sendError);
        }

        // Don't process regular automations when outside business hours
        return [{
          type: 'out_of_hours_message',
          message: phoneLine.out_of_hours_message
        }];
      }

      // Within business hours or no out_of_hours_message configured - process normal automations
      const automationResults = [];

      // 1. Check for keyword triggers (exact and partial matches)
      const keywordResults = await AutomationService.processTrigger({
        lineId,
        triggerType: 'KEYWORD',
        triggerValue: messageContent.trim(),
        templateId: null,
        context: {
          leadId,
          phoneNumber,
          messageContent,
          messageType
        }
      });
      automationResults.push(...keywordResults);

      // 2. Check for general MESSAGE_RECEIVED triggers (catch-all auto-responses)
      // These are rules without specific trigger_value that apply to any message
      const generalResults = await AutomationService.processTrigger({
        lineId,
        triggerType: 'MESSAGE_RECEIVED',
        triggerValue: null,
        templateId: null,
        context: {
          leadId,
          phoneNumber,
          messageContent,
          messageType
        }
      });
      automationResults.push(...generalResults);

      if (automationResults.length > 0) {
        console.log('[WebhookService] Automation rules executed:', automationResults.length);
      }

      return automationResults;
    } catch (error) {
      console.error('[WebhookService] Error processing message automation:', error);
      // Don't throw, automation errors shouldn't break message processing
      return [];
    }
  }

  /**
   * Process button reply and trigger automations
   * @param {number} lineId - WhatsApp line ID
   * @param {number} leadId - Lead ID
   * @param {string} phoneNumber - Sender's phone number
   * @param {Object} buttonReply - Button reply data
   * @returns {Promise<Array>} Executed automations
   */
  async processButtonReply(lineId, leadId, phoneNumber, buttonReply) {
    try {
      console.log('Processing button reply:', JSON.stringify(buttonReply, null, 2));

      const { id: buttonId, title: buttonText } = buttonReply;

      // Trigger automation rules for QUICK_REPLY
      const automationResults = await AutomationService.processTrigger({
        lineId,
        triggerType: 'QUICK_REPLY',
        triggerValue: buttonText,
        templateId: null, // Could be enhanced to track which template triggered this
        context: {
          leadId,
          phoneNumber,
          buttonId,
          buttonText
        }
      });

      console.log('Automation results:', automationResults);

      // Emit socket event for button click
      SocketService.emitToLine(lineId, 'button:clicked', {
        leadId,
        phoneNumber,
        buttonId,
        buttonText,
        automationResults
      });

      return automationResults;
    } catch (error) {
      console.error('Error processing button reply:', error);
      // Don't throw, automation errors shouldn't break message processing
      return [];
    }
  }

  /**
   * Verify webhook signature (Meta HMAC SHA256)
   * @param {string} signature - X-Hub-Signature-256 header value
   * @param {string} rawBody - Raw request body
   * @param {string} secret - Webhook secret from line configuration
   * @returns {boolean} Verification result
   */
  verifyWebhookSignature(signature, rawBody, secret) {
    try {
      if (!signature || !rawBody || !secret) {
        return false;
      }

      // Extract the signature value (format: sha256=<signature>)
      const signatureHash = signature.replace('sha256=', '');

      // Compute HMAC SHA256
      const expectedHash = crypto
        .createHmac('sha256', secret)
        .update(rawBody, 'utf8')
        .digest('hex');

      // Constant-time comparison
      return crypto.timingSafeEqual(
        Buffer.from(signatureHash, 'hex'),
        Buffer.from(expectedHash, 'hex')
      );
    } catch (error) {
      console.error('Error verifying webhook signature:', error);
      return false;
    }
  }
}

export default new WebhookService();

