module.exports = {
  async up(queryInterface, Sequelize) {
    await queryInterface.createTable('leads', {
      id: {
        type: Sequelize.INTEGER,
        primaryKey: true,
        autoIncrement: true,
        allowNull: false,
      },
      phone_number: {
        type: Sequelize.STRING(20),
        allowNull: false,
        unique: true,
      },
      name: {
        type: Sequelize.STRING(100),
        allowNull: true,
      },
      email: {
        type: Sequelize.STRING(255),
        allowNull: true,
      },
      status: {
        type: Sequelize.ENUM('new', 'contacted', 'qualified', 'converted', 'lost'),
        allowNull: false,
        defaultValue: 'new',
      },
      notes: {
        type: Sequelize.TEXT,
        allowNull: true,
      },
      first_contact_date: {
        type: Sequelize.DATE,
        allowNull: false,
        defaultValue: Sequelize.literal('CURRENT_TIMESTAMP'),
      },
      created_at: {
        type: Sequelize.DATE,
        allowNull: false,
        defaultValue: Sequelize.literal('CURRENT_TIMESTAMP'),
      },
      updated_at: {
        type: Sequelize.DATE,
        allowNull: false,
        defaultValue: Sequelize.literal('CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP'),
      },
      deleted_at: {
        type: Sequelize.DATE,
        allowNull: true,
        comment: 'Soft delete timestamp - paranoid mode',
      },
    });

    // Create indexes
    await queryInterface.addIndex('leads', ['phone_number'], {
      unique: true,
      name: 'idx_leads_phone',
    });

    await queryInterface.addIndex('leads', ['status', 'deleted_at'], {
      name: 'idx_leads_status',
    });

    await queryInterface.addIndex('leads', ['first_contact_date'], {
      name: 'idx_leads_first_contact',
    });

    await queryInterface.addIndex('leads', ['deleted_at'], {
      name: 'idx_leads_deleted',
    });

    // Note: FULLTEXT index for name field - MySQL specific
    await queryInterface.sequelize.query(
      'CREATE FULLTEXT INDEX idx_leads_name_search ON leads (name)'
    );
  },

  async down(queryInterface, Sequelize) {
    await queryInterface.dropTable('leads');
  },
};

